print("CODICE FILE        | T08 a sistema | FASI | MATERIALE | COMPONENTI")
for c in sorted(D):
    d = D[c]
    n = c.split("-")[-1]
    t = "T08-0100-" + n
    if c.startswith("T08-0200"):
        t = c
    bom = frappe.db.get_value("Item", t, "default_bom")
    if not bom:
        print(c, "|", t, "NON ESISTE")
        continue
    bq = frappe.db.get_value("BOM", bom, "quantity") or 1
    ops = []
    for r in frappe.db.sql("SELECT description FROM `tabBOM Operation` WHERE parent=%s ORDER BY idx", bom):
        txt = frappe.utils.strip_html(r[0] or "").strip()
        tok = txt.split(" ")[0]
        ops.append(tok.split("-")[-1])
    mat = []
    ch = []
    for r in frappe.db.sql("SELECT item_code, qty FROM `tabBOM Item` WHERE parent=%s ORDER BY idx", bom):
        if r[0].startswith("T0"):
            ch.append([r[0].split("-")[-1], round(float(r[1]) / float(bq), 4)])
        else:
            mat.append(r[0])
    fo = "OK" if ops == d["ops"] else "DIVERSE"
    fm = "OK" if sorted(mat) == sorted(d["mat"]) else "DIVERSO"
    fc = "OK" if sorted(ch) == sorted(d["ch"]) else "DIVERSI"
    print(c, "|", t, "|", fo, "|", fm, "|", fc)
    if fo != "OK":
        print("     fasi file:", d["ops"])
        print("     fasi T08 :", ops)
    if fm != "OK":
        print("     mat file:", d["mat"], "| mat T08:", mat)
    if fc != "OK":
        print("     comp file:", sorted(d["ch"]))
        print("     comp T08 :", sorted(ch))
